const topicinput = document.querySelector("input");
const generatebtn = document.querySelector("button");
const notesoutput = document.querySelector("#notesoutput");
const copyBtn = document.querySelector("#copyBtn");
const downloadBtn = document.querySelector("#downloadBtn");

// Escape HTML so AI output is displayed safely
function escapeHTML(text) {
    return text
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
}


// Convert Markdown generated by Gemini into clean HTML
function formatNotes(markdown) {

    let text = escapeHTML(markdown);

    const lines = text.split("\n");
    let html = "";
    let inList = false;
    let inTable = false;

    for (let i = 0; i < lines.length; i++) {

        let line = lines[i].trim();

        // Empty line
        if (line === "") {
            if (inList) {
                html += "</ul>";
                inList = false;
            }

            if (inTable) {
                html += "</tbody></table>";
                inTable = false;
            }

            continue;
        }


        // Horizontal line
        if (line === "---" || line === "***") {

            if (inList) {
                html += "</ul>";
                inList = false;
            }

            html += "<hr>";
            continue;
        }


        // Markdown table
        if (line.startsWith("|")) {

            const cells = line
                .split("|")
                .slice(1, -1)
                .map(cell => cell.trim());

            // Skip separator row
            if (cells.every(cell => /^[-:]+$/.test(cell))) {
                continue;
            }

            if (!inTable) {

                html += `
                    <div class="table-wrapper">
                    <table>
                        <thead>
                            <tr>
                `;

                cells.forEach(cell => {
                    html += `<th>${formatInline(cell)}</th>`;
                });

                html += `
                            </tr>
                        </thead>
                        <tbody>
                `;

                inTable = true;

            } else {

                html += "<tr>";

                cells.forEach(cell => {
                    html += `<td>${formatInline(cell)}</td>`;
                });

                html += "</tr>";
            }

            continue;
        }


        // Headings
        if (line.startsWith("### ")) {

            html += `<h3>${formatInline(line.substring(4))}</h3>`;
            continue;

        }

        if (line.startsWith("## ")) {

            html += `<h2>${formatInline(line.substring(3))}</h2>`;
            continue;

        }

        if (line.startsWith("# ")) {

            html += `<h1>${formatInline(line.substring(2))}</h1>`;
            continue;
        }


        // Bullet points
        if (line.startsWith("* ") || line.startsWith("- ")) {

            if (!inList) {
                html += "<ul>";
                inList = true;
            }

            html += `<li>${formatInline(line.substring(2))}</li>`;
            continue;
        }


        // Numbered list
        if (/^\d+\.\s/.test(line)) {

            if (inList) {
                html += "</ul>";
                inList = false;
            }

            const number = line.match(/^\d+/)[0];
            const content = line.replace(/^\d+\.\s/, "");

            html += `<p class="numbered">
                        <strong>${number}.</strong> ${formatInline(content)}
                     </p>`;

            continue;
        }


        // Normal paragraph
        if (inList) {
            html += "</ul>";
            inList = false;
        }

        html += `<p>${formatInline(line)}</p>`;
    }


    // Close anything still open
    if (inList) {
        html += "</ul>";
    }

    if (inTable) {
        html += "</tbody></table></div>";
    }


    return html;
}


// Format bold, italic and inline code
function formatInline(text) {

    return text

        // Bold
        .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>")

        // Italic
        .replace(/\*(.*?)\*/g, "<em>$1</em>")

        // Inline code
        .replace(/`(.*?)`/g, "<code>$1</code>");
}


// Generate notes
generatebtn.addEventListener("click", async function () {

    const topic = topicinput.value.trim();


    // Empty topic
    if (topic === "") {

        notesoutput.textContent = "Please enter a topic.";

        return;
    }


    // Loading message
    notesoutput.innerHTML = `
    <div class="loading-box">

        <div class="loading-spinner"></div>

        <div class="loading-text">
            Creating your study notes...
        </div>

        <div class="loading-subtext">
            AI is organizing the topic for you ✨
        </div>

    </div>
`;


    try {

        const response = await fetch("/generate", {

            method: "POST",

            headers: {
                "Content-Type": "application/json"
            },

            body: JSON.stringify({
                topic: topic
            })
        });


        if (!response.ok) {
            throw new Error("Server error: " + response.status);
        }


       const data = await response.json();


// Check if backend reported an error
if (!response.ok || data.success === false) {

    notesoutput.innerHTML = `
        <div class="error-box">

            <div class="error-icon">⚠️</div>

            <h3>Something went wrong</h3>

            <p>${data.message}</p>

            <button id="retryBtn">
                🔄 Try Again
            </button>

        </div>
    `;

    // Retry button
    document.querySelector("#retryBtn").addEventListener("click", function () {
        generatebtn.click();
    });

    return;
}


// Display successful notes
notesoutput.innerHTML = formatNotes(data.message);

    } catch (error) {

        console.error("Generation error:", error);

        notesoutput.innerHTML = `
            <div class="error">
                ❌ Something went wrong.
                <br>
                Please make sure the Python server is running.
            </div>
        `;
    }

});
copyBtn.addEventListener("click", async function () {

    const notes = notesoutput.innerText.trim();

    if (!notes || notes === "Your notes will appear here...") {
        alert("Please generate notes first.");
        return;
    }

    try {

        await navigator.clipboard.writeText(notes);

        copyBtn.textContent = "✅ Copied!";

        setTimeout(() => {
            copyBtn.textContent = "📋 Copy Notes";
        }, 2000);

    } catch (error) {

        alert("Unable to copy notes.");

    }

});
downloadBtn.addEventListener("click", function () {

    const notes = notesoutput.innerText.trim();

    if (!notes || notes === "Your notes will appear here...") {
        alert("Please generate notes first.");
        return;
    }

    const blob = new Blob([notes], {
        type: "text/plain"
    });

    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");

    link.href = url;
    link.download = "AI-Study-Notes.txt";

    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);

    URL.revokeObjectURL(url);

});